<script>(()=>{const root=document.getElementById('four-player-game'),button=document.getElementById('four-rematch');if(!button)return;button.onclick=async()=>{button.disabled=true;try{const r=await fetch(root.dataset.rematchUrl,{method:'POST',headers:{'Content-Type':'application/json','X-Requested-With':'XMLHttpRequest'},body:JSON.stringify({[root.dataset.csrfName]:root.dataset.csrfHash})}),p=await r.json();if(p.csrfHash)root.dataset.csrfHash=p.csrfHash;if(!r.ok)throw Error(p.message);button.textContent=p.room.status==='playing'?'Oyun başlıyor…':'Diğer oyuncular bekleniyor…';if(p.room.status==='playing')location.reload()}catch(e){button.disabled=false;button.textContent=e.message}}})();</script>
<script>(()=>{const r=document.getElementById('four-player-game'),b=document.getElementById('four-rematch');if(!r||!b)return;setInterval(async()=>{try{const x=await fetch(r.dataset.stateUrl),p=await x.json();if(p.success)b.hidden=p.room.status!=='completed'}catch{}},3000)})();</script>
<script>(()=>{const root=document.getElementById('four-player-game'),panel=document.getElementById('four-rematch-panel'),button=document.getElementById('four-rematch'),note=document.getElementById('four-rematch-note');if(!root||!panel||!button)return;const show=status=>{const visible=status==='completed';panel.classList.toggle('is-visible',visible);panel.setAttribute('aria-hidden',visible?'false':'true');button.hidden=false};button.onclick=async()=>{button.disabled=true;note.textContent='Hazır olduğun bildiriliyor…';try{const response=await fetch(root.dataset.rematchUrl,{method:'POST',headers:{'Content-Type':'application/json','X-Requested-With':'XMLHttpRequest'},body:JSON.stringify({[root.dataset.csrfName]:root.dataset.csrfHash})}),payload=await response.json();if(payload.csrfHash)root.dataset.csrfHash=payload.csrfHash;if(!response.ok)throw Error(payload.message);if(payload.room.status==='playing'){note.textContent='Herkes hazır. Yeni oyun başlıyor…';location.reload();return}button.textContent='Hazırsın';note.textContent='Diğer oyuncuların hazır olması bekleniyor.'}catch(error){button.disabled=false;note.textContent=error.message}};setInterval(async()=>{try{const response=await fetch(root.dataset.stateUrl),payload=await response.json();if(!payload.success)return;show(payload.room.status);if(payload.room.status==='playing'&&button.disabled)location.reload()}catch{}},3000)})();</script>
